let sbRefreshPromise=null;
async function renewSession(){if(!sbSession?.refresh_token)throw Error('Sesi berakhir. Silakan login kembali.');if(!sbRefreshPromise)sbRefreshPromise=(async()=>{const r=await fetch(SB_URL+'/auth/v1/token?grant_type=refresh_token',{method:'POST',headers:{apikey:SB_KEY,'Content-Type':'application/json'},body:JSON.stringify({refresh_token:sbSession.refresh_token})});const d=await r.json().catch(()=>null);if(!r.ok||!d?.access_token)throw Error('Sesi berakhir. Silakan login kembali.');sbSession=d;localStorage.setItem('buzzo_session',JSON.stringify(d));return d})().finally(()=>{sbRefreshPromise=null});return sbRefreshPromise}
async function api(path,options={}){const request=()=>fetch(SB_URL+path,{...options,headers:{'apikey':SB_KEY,'Content-Type':'application/json',...(sbSession?.access_token?{'Authorization':'Bearer '+sbSession.access_token}:{}),...options.headers}});let r=await request();if(r.status===401&&sbSession?.refresh_token&&path.startsWith('/rest/')){await renewSession();r=await request()}let d=await r.json().catch(()=>null);if(!r.ok)throw Error(d?.msg||d?.message||d?.error_description||d?.error||'Permintaan gagal');return d}
async function refreshSession(){if(!sbSession)return;try{if(sbSession.expires_at*1000<Date.now()+60000){const v=await api('/auth/v1/token?grant_type=refresh_token',{method:'POST',body:JSON.stringify({refresh_token:sbSession.refresh_token})});sbSession=v;localStorage.setItem('buzzo_session',JSON.stringify(v))}sbAdmin=await api('/rest/v1/rpc/jjta_is_admin',{method:'POST',body:'{}'});const p=await api('/rest/v1/jjta_profiles?select=*&user_id=eq.'+encodeURIComponent(sbSession.user.id));sbProfile=p[0]||null;updateAccountButton()}catch(e){sbSession=null;localStorage.removeItem('buzzo_session');updateAccountButton()}}
