document.addEventListener('click',e=>{let b=e.target.closest('button');if(!b)return;if(b.matches('[data-sb-close]')){authBox().hidden=true;document.body.classList.remove('auth-open');return}if(b.matches('[data-sb-register]')){showAuth('register');return}if(b.matches('[data-sb-login]')){showAuth('login');return}if(b.matches('[data-sb-logout]')){sbSession=null;sbAdmin=false;sbProfile=null;localStorage.removeItem('buzzo_session');authBox().hidden=true;document.body.classList.remove('auth-open');updateAccountButton();return}if(b.dataset.sbView){portal(b.dataset.sbView);return}if(b.hasAttribute('data-sb-consult')){closeModal();portal('consultations');return}},true);
