document.addEventListener('submit',async e=>{let f=e.target;if(!['sb-login','sb-register','sb-consult'].includes(f.id))return;e.preventDefault();e.stopImmediatePropagation();let message=f.querySelector('.sb-message'),button=f.querySelector('button[type=submit],button:not([type])');if(button)button.disabled=true;message.textContent='Memproses…';try{let d=Object.fromEntries(new FormData(f));if(f.id==='sb-login'){let v=await api('/auth/v1/token?grant_type=password',{method:'POST',body:JSON.stringify({email:d.email,password:d.password})});sbSession=v;localStorage.setItem('buzzo_session',JSON.stringify(v));await refreshSession();await portal()}else if(f.id==='sb-register'){if(d.invite_code.trim().toUpperCase()!=='JAKARTANOV')throw Error('Kode undangan tidak valid.');if(d.password!==d.password_confirm)throw Error('Konfirmasi password belum cocok.');let {email,password,password_confirm,...metadata}=d;metadata.interests=JSON.parse(metadata.interests||'[]');let v=await api('/auth/v1/signup',{method:'POST',body:JSON.stringify({email,password,data:metadata})});if(v.access_token){sbSession=v;localStorage.setItem('buzzo_session',JSON.stringify(v));await refreshSession();await portal()}else{f.reset();message.textContent='Pendaftaran diterima. Cek email untuk verifikasi, lalu login.'}}else{await api('/rest/v1/jjta_consultations',{method:'POST',headers:{Prefer:'return=minimal'},body:JSON.stringify({...d,user_id:sbSession.user.id})});await portal('consultations')}}catch(err){message.textContent='Gagal: '+err.message}finally{if(button)button.disabled=false}},true);
