async function handleEmailConfirmation(){
 const hash=new URLSearchParams(location.hash.slice(1));
 if(hash.get('type')!=='signup'&&!hash.has('error_description'))return;
 const token=hash.get('access_token'),refresh=hash.get('refresh_token'),error=hash.get('error_description');
 history.replaceState(null,'',location.pathname+location.search);
 if(error){showAuth('login');const msg=document.querySelector('#sb-login .sb-message');if(msg)msg.textContent='Verifikasi gagal: '+error;return}
 if(!token||!refresh){showAuth('login');return}
 try{const user=await api('/auth/v1/user',{headers:{Authorization:'Bearer '+token}});sbSession={access_token:token,refresh_token:refresh,expires_at:Math.floor(Date.now()/1000)+Number(hash.get('expires_in')||3600),user};localStorage.setItem('buzzo_session',JSON.stringify(sbSession));await refreshSession();await portal()}catch(e){showAuth('login');const msg=document.querySelector('#sb-login .sb-message');if(msg)msg.textContent='Email terverifikasi. Silakan login.'}
}
handleEmailConfirmation();


document.addEventListener('change',async e=>{
 const el=e.target.closest('[data-consult-status]');if(!el)return;
 const previous=el.dataset.originalStatus, next=el.value, message=el.parentElement.querySelector('.consult-status-message');
 el.disabled=true;message.textContent='Menyimpan…';
 try{const rows=await api('/rest/v1/jjta_consultations?id=eq.'+encodeURIComponent(el.dataset.consultStatus),{method:'PATCH',headers:{Prefer:'return=representation'},body:JSON.stringify({status:next})});if(!Array.isArray(rows)||rows.length!==1)throw Error('Status tidak tersimpan.');el.dataset.originalStatus=next;message.textContent='Tersimpan';}
 catch(err){el.value=previous;message.textContent='Gagal: '+err.message;}finally{el.disabled=false}
},true);
